import csv, json, datetime, os
rows = list(csv.DictReader(open("data.csv")))
def parse_month(s):
    return datetime.datetime.strptime(s, "%Y-%m")
months = sorted({r["month"] for r in rows}, key=parse_month)
latest_month = months[-1]
year, mon = map(int, latest_month.split("-"))
next_month = f"{year+1:04d}-01" if mon==12 else f"{year:04d}-{mon+1:02d}"
band_vals = {}
for r in rows:
    band = r["band"]
    band_vals.setdefault(band, []).append(float(r["mean_value"]))
prediction = {b: sum(v)/len(v) for b,v in band_vals.items()}
answer = {"prediction": prediction, "rationale": f"Simple average forecast for next month {next_month} based on historical means."}
with open("answer.json","w") as f:
    json.dump(answer, f, indent=2)
print("answer.json written, size:", os.path.getsize("answer.json"))
